import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

/**
 * Creates a pricing card label node – a static plane with image and text.
 * @param {import('@/primitives').NodeConfig} config
 * @param {import('@/primitives').NodeContext} ctx
 * @returns {THREE.Group}
 */
export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // --- Position / Rotation / Scale ---
  const pos = config.scenePlacement?.position ?? [3.2, 1, 0.06];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  // --- Image plane ---
  const imageUrl = config.assets?.imageUrl ?? '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Source rect from atlas region: 0,0,512,320 → use full texture
  // (Assume texture already contains the exact region; if not, we could offset/scale UVs)
  const imageGeometry = new THREE.PlaneGeometry(1, 0.625); // 512x320 aspect = 1.6 → width 1, height 0.625
  const imageMaterial = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
  });
  const imageMesh = new THREE.Mesh(imageGeometry, imageMaterial);
  // Place image centered at origin of this group
  imageMesh.position.set(0, 0, 0);
  group.add(imageMesh);

  // --- Text label ---
  const textContent = config.textContent?.headline ?? 'Pricing 3';
  // Use ctx.fontAtlas (assumed synchronous) to create text mesh
  // Font: display serif, size 39px → convert to scene units (with DPR scaling)
  const dpr = window.devicePixelRatio || 1;
  const fontSize = (39 / dpr) * 0.001; // rough scale factor to scene units; fine‑tune as needed
  const textMesh = ctx.fontAtlas.createMesh(textContent, {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: fontSize,
    color: new THREE.Color('#e8ecf2'), // paper
    align: 'center',
    baseline: 'middle',
  });
  // Position text slightly in front of image plane
  textMesh.position.set(0, 0, 0.002);
  group.add(textMesh);

  // --- Handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill any GSAP timelines (none in this case)
    imageMaterial.dispose();
    imageGeometry.dispose();
    texture.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    // Remove from parent if still attached
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
